class Solution {
  public int mostFrequentElement(int[] nums) {

    int length = nums.length;

    int count = 1;
    int max = Integer.MIN_VALUE;
    int el = nums[0];
    Arrays.sort(nums);
    // System.out.println(Arrays.toString(nums));

    for (int i = 1; i < length; i++) {

      if (nums[i] == nums[i - 1]) {
        count++;
      } else {
        count = 1;
      }

      if (count > max) {
        max = count;
        el = nums[i - 1];
      } else if (count == max && nums[i] < el) {
        el = nums[i - 1];
      }
    }

    return el;
  }
}

